//go:build arm64

package floats

// The NEON kernel of the squared magnitude (sqmag.go), generated by go-asmgen
// (sqmag_arm64_gen.go) into sqmag_arm64.s: two bins per step; the Go code finishes
// the odd one. NEON is the ARMv8-A baseline: no gate. No kernel keeps a pointer:
// go:noescape.
//
//go:noescape
func sqmagNEON(dst, c []float64, s float64)

func squaredMagnitude(dst, c []float64, s float64) {
	sqmagNEON(dst, c, s)
	sqmagTail(dst, c, s, len(dst)&^1)
}
